def maxSumOfSquares(num: int, sum: int) -> str:
    S = sum
    if S < 1 or S > 9 * num:
        return ""
    q = S // 9
    r = S % 9
    parts = ['9'] * q
    if r > 0:
        parts.append(str(r))
    parts.extend(['0'] * (num - len(parts)))
    return ''.join(parts)
